```js
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu'
import { uv, vec2, smoothstep, distance } from 'three/tsl'
import { gsap } from 'gsap'

export default function createNode(config, ctx) {
  const THREE = ctx.THREE
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry,
    DirectionalLight, PointLight, Color, Box3, Vector3
  } = THREE

  const colors = config.intent?.visualSpec?.colors ?? {}
  const ink     = colors.ink     ?? '#16161d'
  const paper   = colors.paper   ?? '#e8ecf2'
  const accent  = colors.accent  ?? '#ff2a38'
  const surface = colors.surface ?? '#0b0b10'

  const root = new Group()
  root.name = 'thumb-card-gear-a'

  // inner group holds all visuals so scenePosition (applied by adapter)
  // never fights our entrance/interaction transforms.
  const inner = new Group()
  root.add(inner)

  // ---- Card panel (machined-metal PBR) ----
  const cardW = 2.2, cardH = 2.8, cardD = 0.1
  const cardMat = new MeshStandardNodeMaterial()
  cardMat.color.set(surface)
  cardMat.roughness = 0.55
  cardMat.metalness = 0.42
  cardMat.clearcoat = 0.22
  cardMat.clearcoatRoughness = 0.45
  const card = new Mesh(new BoxGeometry(cardW, cardH, cardD), cardMat)
  card.castShadow = true
  card.receiveShadow = true
  inner.add(card)

  // ---- Inset display recess (front face) ----
  const insetBase = new Color(ink).multiplyScalar(0.55)
  const insetMat = new MeshStandardNodeMaterial()
  insetMat.color.set(insetBase)
  insetMat.roughness = 0.5
  insetMat.metalness = 0.5
  const inset = new Mesh(new PlaneGeometry(cardW * 0.86, cardH * 0.7), insetMat)
  inset.position.set(0, 0.2, cardD / 2 + 0.002)
  inner.add(inset)

  // thin machined rim around inset
  const rimMat = new MeshStandardNodeMaterial()
  rimMat.color.set(new Color(paper).multiplyScalar(0.35))
  rimMat.roughness = 0.4
  rimMat.metalness = 0.6
  const rim = new Mesh(new BoxGeometry(cardW * 0.88, cardH * 0.72, 0.02), rimMat)
  rim.position.set(0, 0.2, cardD / 2 - 0.01)
  inner.add(rim)

  // ---- Caption strip ----
  const stripMat = new MeshStandardNodeMaterial()
  stripMat.color.set(new Color(surface).lerp(new Color(ink), 0.45))
  stripMat.roughness = 0.62
  stripMat.metalness = 0.22
  const strip = new Mesh(new PlaneGeometry(cardW * 0.86, cardH * 0.14), stripMat)
  strip.position.set(0, -cardH * 0.36, cardD / 2 + 0.003)
  inner.add(strip)

  // ---- Accent edge (signal-red hairline) ----
  const accentMat = new MeshStandardNodeMaterial()
  accentMat.color.set(accent)
  accentMat.emissive.set(accent)
  accentMat.emissiveIntensity = 1.15
  accentMat.roughness = 0.4
  accentMat.metalness = 0.3
  const accentEdge = new Mesh(new BoxGeometry(cardW * 0.86, 0.035, 0.02), accentMat)
  accentEdge.position.set(0, -cardH * 0.36 - cardH * 0.075, cardD / 2 + 0.01)
  inner.add(accentEdge)

  // small accent index dot (caption marker)
  const dotMat = new MeshStandardNodeMaterial()
  dotMat.color.set(accent)
  dotMat.emissive.set(accent)
  dotMat.emissiveIntensity = 0.9
  const dot = new Mesh(new PlaneGeometry(0.08, 0.08), dotMat)
  dot.position.set(-cardW * 0.34, -cardH * 0.36, cardD / 2 + 0.004)
  inner.add(dot)

  // ---- Contact shadow (radial alpha via TSL) ----
  const shadowMat = new MeshBasicNodeMaterial()
  shadowMat.color.set(0x000000)
  shadowMat.transparent = true
  shadowMat.depthWrite = false
  const radUv = uv().sub(vec2(0.5, 0.5)).mul(2.0)
  const r = distance(radUv.x, radUv.y)
  shadowMat.opacityNode = smoothstep(1.0, 0.15, r).mul(0.55)
  const shadow = new Mesh(new PlaneGeometry(2.7, 2.7), shadowMat)
  shadow.rotation.x = -Math.PI / 2
  shadow.position.set(0, -cardH / 2 - 0.015, 0)
  inner.add(shadow)

  // ---- Local rim + accent lights ----
  const accentLight = new PointLight(new Color(accent), 0.55, 6.0, 2.0)
  accentLight.position.set(-1.6, 0.5, 1.5)
  inner.add(accentLight)

  const fillLight = new DirectionalLight(new Color(paper), 0.3)
  fillLight.position.set(1.8, 1.2, 2.2)
  inner.add(fillLight)

  // ---- Gear GLB load ----
  let gearCleanup = () => {}
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf
      const box = new Box3().setFromObject(scene)
      const size = new Vector3()
      box.getSize(size)
      const maxDim = Math.max(size.x, size.y, size.z) || 1
      const fit = 1.45 / maxDim
      scene.scale.multiplyScalar(fit)
      const center = new Vector3()
      box.getCenter(center)
      scene.position.sub(center.multiplyScalar(fit))
      scene.position.y += 0.22
      scene.position.z += cardD / 2 + 0.14
      inner.add(scene)
      // gentle idle breathe
      gsap.to(scene.scale, {
        x: scene.scale.x * 1.03, y: scene.scale.y * 1.03, z: scene.scale.z * 1.03,
        duration: 3.2, ease: 'sine.inOut', yoyo: true, repeat: -1
      })
      gearCleanup = () => {
        scene.traverse((o) => {
          if (o.geometry) o.geometry.dispose?.()
          if (o.material) {
            const mats = Array.isArray(o.material) ? o.material : [o.material]
            mats.forEach((m) => m.dispose?.())
          }
        })
      }
    })
  }

  // ---- Entrance: rise-in ----
  inner.position.y = 0.4
  const tl = gsap.timeline()
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' })
  tl.fromTo(inner.scale, { x: 0.96, y: 0.96, z: 0.96 }, {
    x: 1.04, y: 1.04, z: 1.04, duration: 0.55, ease: 'power3.out'
  }, '<0.05')
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' })

  // ---- Handlers ----
  let hoverTween = null
  leafHover: {}
  inner.userData = {}
  root.userData.handlers = {
    onPointerEnter: () => {
      hoverTween = gsap.to(inner.position, { y: 0.15, duration: 0.45, ease: 'power2.out' })
      gsap.to(inner.rotation, { z: 0.04, duration: 0.3, ease: 'power2.out' })
    },
    onPointerLeave: () => {
      if (hoverTween) hoverTween.kill()
      gsap.to(inner.position, { y: 0, duration: 0.4, ease: 'power3.out' })
      gsap.to(inner.rotation, { z: 0, duration: 0.4, ease: 'power3.out' })
    },
    onClick: () => {
      const press = gsap.timeline()
      press.to(inner.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' })
             .to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.34, ease: 'back.out(2.2)' })
      ctx.emit('hub-home.select', { id: config.id ?? 'gear-a', mesh: config.meshUrl })
    }
  }

  // ---- Cleanup ----
  const disposables = [
    [card.geometry, cardMat],
    [inset.geometry, insetMat],
    [rim.geometry, rimMat],
    [strip.geometry, stripMat],
    [accentEdge.geometry, accentMat],
    [dot.geometry, dotMat],
    [shadow.geometry, shadowMat]
  ]
  root.userData.cleanup = () => {
    tl.kill()
    if (hoverTween) hoverTween.kill()
    gsap.killTweensOf(inner.position)
    gsap.killTweensOf(inner.scale)
    gsap.killTweensOf(inner.rotation)
    gearCleanup()
    disposables.forEach(([geo, mat]) => {
      geo.dispose?.()
      mat.dispose?.()
    })
  }

  return root
}
